deepml vfx 0.3
module corpus.deepml_vfx.example_02751
policy deterministic
policy no_network
effect Effect02751 {
  coupled simulation PortalSim seed 2751 { fluid: Energy cloth: Veil particles: Sparks }
  procedural operator Distort(time, portal_state) differentiable
  cache PortalCache1 interval 0s..10s step 1/60s hash sha256("cache:02751")
  bind scene PortalScene14
  bind timeline PortalSequence8
  render_graph { Sim -> Lighting -> Distortion -> Composite }
  composite multipass [SceneColor, PortalGlow, Distortion, Atmosphere]
}

